internal val GARMIN_POSE_TITLES: Map<Long, String> by lazy {
    val table = HashMap<Long, String>(3400)
    for (chunk in POSE_TITLE_CHUNKS) {
        for (row in chunk.lineSequence()) {
            if (row.isEmpty()) continue
            val first = row.indexOf(':')
            val second = row.indexOf(':', first + 1)
            val category = row.substring(0, first).toLong()
            val name = row.substring(first + 1, second).toLong()
            table[(category shl 32) or name] = row.substring(second + 1)
        }
    }
    table
}
